import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

const PANE = 'auto-allow'
// Persisted across sessions in $.store; off until toggled on.
const STORE_KEY = 'enabled'

const enabledAtom = atom({ plugin: 'auto-allow', key: 'enabled' } as const, false)
const frameAtom = atom({ plugin: 'auto-allow', key: 'frame' } as const, 0)

// The dog chases a ball back and forth while auto-allow is on.
const PLAY = [
  ['      o       ', '(ᵔᴥᵔ)        '],
  ['     o        ', ' (ᵔᴥᵔ)       '],
  ['   o          ', '  (ᵔᴥᵔ)ﾉ     '],
  ['       o      ', '   ٩(ᵔᴥᵔ)    '],
  ['          o   ', '    (ᵔᴥᵔ)    '],
  ['            o ', '     (ᵔᴥᵔ)ﾉ  '],
  ['         o    ', '    ٩(ᵔᴥᵔ)   '],
  ['        o     ', '   (ᵔᴥᵔ)     '],
]
const SLEEP = [
  ['        z     ', '(-ᴥ-)        '],
  ['         zZ   ', '(-ᴥ-)        '],
]

async function isEnabled($: EngineInterface): Promise<boolean> {
  return read($, enabledAtom)
}

async function setEnabled($: EngineInterface, enabled: boolean): Promise<void> {
  await $.store.set(STORE_KEY, enabled)
  await update($, enabledAtom, () => enabled)
  $.ui.status(enabled ? 'auto-allow: ON' : undefined)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'auto-allow',
      description: 'Toggle auto-approving all permissions (on | off | status | show)',
    })
    await setEnabled($, ((await $.store.get(STORE_KEY)) ?? false) === true)
    void $.ui.open({ id: PANE, title: 'auto-allow' })
    $.clock.every(350, () => update($, frameAtom, f => (f + 1) % 1000))

    return next(e)
  })

  on('command.run', { command: 'auto-allow' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    const current = await isEnabled($)

    if (arg === 'status') {
      return { text: `auto-allow is ${current ? 'ON' : 'OFF'}.` }
    }
    if (arg === 'show') {
      await $.ui.open({ id: PANE, title: 'auto-allow' })
      return { text: 'auto-allow pane opened.' }
    }

    const enabled = arg === 'on' ? true : arg === 'off' ? false : !current
    await setEnabled($, enabled)

    return {
      text: enabled
        ? 'auto-allow ON: every tool call and permission prompt is approved automatically.'
        : 'auto-allow OFF: normal permission prompts are back.',
    }
  })

  // Approve before the permission check runs, so no prompt is raised.
  on('classic.PreToolUse', async ($, e, next) =>
    (await isEnabled($)) ? { allow: true } : next(e),
  ).catch(($, e, next) => next(e))

  // Answer any permission dialog that still comes up.
  on('classic.PermissionRequest', async ($, e, next) =>
    (await isEnabled($)) ? { decision: { behavior: 'allow' } } : next(e),
  ).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const enabled = await read($, enabledAtom)
    const frame = await read($, frameAtom)
    const frames = enabled ? PLAY : SLEEP
    const [ball, dog] = frames[Math.floor(frame / (enabled ? 1 : 3)) % frames.length] ?? ['', '']

    return (
      <Box flexDirection="column">
        <Text bold>{enabled ? 'auto-allow: ON' : 'auto-allow: OFF'}</Text>
        <Text>{ball}</Text>
        <Text>{dog}</Text>
        <Text dimColor>
          {enabled ? 'approving everything' : 'prompts are back'}
        </Text>
        <Text dimColor>/auto-allow to toggle</Text>
      </Box>
    )
  })
}

